<?php
declare(strict_types=1);
$listUrl=jyb_localized_path($base,$locale);$total=(int)$result['total'];
$pageUrl=static function(int $page)use($filters,$listUrl):string{$query=array_filter(['q'=>$filters['q'],'company'=>$filters['company']?:'','category'=>$filters['category']?:'','employment'=>$filters['employment'],'workplace'=>$filters['workplace'],'featured'=>$filters['featured'],'page_number'=>$page>1?$page:''],static fn(mixed $value):bool=>$value!=='');return $listUrl.($query===[]?'':'?'.http_build_query($query));};
?>
<div class="jyb-public"><header class="jyb-hero"><p class="jyb-eyebrow"><?=jyb_h(jyb_t('Current opportunities'))?></p><h1><?=jyb_h(jyb_t('Find your next role'))?></h1><p><?=jyb_h(jyb_t('Search open positions by company, category, employment type, or workplace.'))?></p></header><form class="jyb-search" method="get" action="<?=jyb_h($listUrl)?>" role="search"><label class="jyb-search-wide"><span><?=jyb_h(jyb_t('Search jobs'))?></span><input type="search" name="q" maxlength="100" value="<?=jyb_h($filters['q'])?>" placeholder="<?=jyb_h(jyb_t('Title, company, or location'))?>"></label><label><span><?=jyb_h(jyb_t('Company'))?></span><select name="company"><option value=""><?=jyb_h(jyb_t('All companies'))?></option><?php foreach($options['companies'] as $company):?><option value="<?=(int)$company['id']?>" <?=$filters['company']===(int)$company['id']?'selected':''?>><?=jyb_h($company['name'])?></option><?php endforeach;?></select></label><label><span><?=jyb_h(jyb_t('Category'))?></span><select name="category"><option value=""><?=jyb_h(jyb_t('All categories'))?></option><?php foreach($options['categories'] as $category):?><option value="<?=(int)$category['id']?>" <?=$filters['category']===(int)$category['id']?'selected':''?>><?=jyb_h($category['name'])?></option><?php endforeach;?></select></label><label><span><?=jyb_h(jyb_t('Employment'))?></span><select name="employment"><option value=""><?=jyb_h(jyb_t('Any employment type'))?></option><?php foreach(jyb_employment_types() as $type):?><option value="<?=$type?>" <?=$filters['employment']===$type?'selected':''?>><?=jyb_h(jyb_t(ucwords(str_replace('-',' ',$type))))?></option><?php endforeach;?></select></label><label><span><?=jyb_h(jyb_t('Workplace'))?></span><select name="workplace"><option value=""><?=jyb_h(jyb_t('Any workplace'))?></option><?php foreach(jyb_workplace_types() as $type):?><option value="<?=$type?>" <?=$filters['workplace']===$type?'selected':''?>><?=jyb_h(jyb_t(ucwords(str_replace('-',' ',$type))))?></option><?php endforeach;?></select></label><label class="jyb-featured"><input type="checkbox" name="featured" value="1" <?=$filters['featured']==='1'?'checked':''?>> <?=jyb_h(jyb_t('Featured only'))?></label><button type="submit"><?=jyb_h(jyb_t('Search'))?></button></form><div class="jyb-result"><strong><?=jyb_h($total===1?jyb_t('1 open job'):jyb_t('%d open jobs',$total))?></strong><?php if(array_filter($filters,static fn(mixed $v):bool=>$v!==''&&$v!==0&&$v!=='1')!==[]):?><a href="<?=jyb_h($listUrl)?>"><?=jyb_h(jyb_t('Clear filters'))?></a><?php endif;?></div>
<?php if($result['rows']===[]):?><section class="jyb-public-empty"><h2><?=jyb_h(jyb_t('No matching jobs'))?></h2><p><?=jyb_h(jyb_t('Try a broader search or another filter.'))?></p></section><?php else:?><section class="jyb-job-grid" aria-label="<?=jyb_h(jyb_t('Open jobs'))?>"><?php foreach($result['rows'] as $job):$url=jyb_localized_path($base.'/'.rawurlencode((string)$job['slug']),$locale);?><article class="jyb-job-card"><div class="jyb-job-card-top"><span><?=jyb_h($job['company_name'])?></span><?php if($job['featured']):?><b><?=jyb_h(jyb_t('Featured'))?></b><?php endif;?></div><h2><a href="<?=jyb_h($url)?>"><?=jyb_h($job['title'])?></a></h2><?php if($job['summary']):?><p><?=jyb_h($job['summary'])?></p><?php endif;?><dl><div><dt><?=jyb_h(jyb_t('Employment'))?></dt><dd><?=jyb_h(jyb_t(ucwords(str_replace('-',' ',(string)$job['employment_type']))))?></dd></div><div><dt><?=jyb_h(jyb_t('Workplace'))?></dt><dd><?=jyb_h(jyb_t(ucwords(str_replace('-',' ',(string)$job['workplace_type']))))?></dd></div><?php if($job['location_text']):?><div><dt><?=jyb_h(jyb_t('Location'))?></dt><dd><?=jyb_h($job['location_text'])?></dd></div><?php endif;?></dl><a class="jyb-card-link" href="<?=jyb_h($url)?>"><?=jyb_h(jyb_t('View role'))?></a></article><?php endforeach;?></section><?php if((int)$result['pages']>1):?><nav class="jyb-public-pagination" aria-label="<?=jyb_h(jyb_t('Job pages'))?>"><?php if((int)$result['page']>1):?><a rel="prev" href="<?=jyb_h($pageUrl((int)$result['page']-1))?>"><?=jyb_h(jyb_t('Previous'))?></a><?php endif;?><span aria-current="page"><?=jyb_h(jyb_t('Page %d of %d',(int)$result['page'],(int)$result['pages']))?></span><?php if((int)$result['page']<(int)$result['pages']):?><a rel="next" href="<?=jyb_h($pageUrl((int)$result['page']+1))?>"><?=jyb_h(jyb_t('Next'))?></a><?php endif;?></nav><?php endif;?><?php endif;?></div>
